#include "PluginEditor.h"
UCGVoiceWonderEditor::UCGVoiceWonderEditor(UCGVoiceWonderProcessor&x):AudioProcessorEditor(&x),p(x){setSize(760,430);title.setText("UCG  VOICE WONDER",juce::dontSendNotification);title.setFont(juce::Font(28,juce::Font::bold));title.setJustificationType(juce::Justification::centred);addAndMakeVisible(title);const char*ids[]={"mix","pitch","correct","radio","vocoder","drive","low","high"};const char*names[]={"MIX","PITCH","TUNE","RADIO","VOCODER","DRIVE","WARMTH","AIR"};for(int i=0;i<8;i++){auto&k=knobs[i];k.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);k.setTextBoxStyle(juce::Slider::TextBoxBelow,false,70,20);k.setName(names[i]);addAndMakeVisible(k);sa.push_back(std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.apvts,ids[i],k));}addAndMakeVisible(midi);ba=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.apvts,"midi",midi);}
void UCGVoiceWonderEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff090e1a));g.setColour(juce::Colour(0xff13233b));g.fillRoundedRectangle(getLocalBounds().toFloat().reduced(18),18);g.setColour(juce::Colour(0xff00d9ff));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(18),18,2);g.setColour(juce::Colours::white.withAlpha(.7f));for(auto&k:knobs)g.drawFittedText(k.getName(),k.getX(),k.getY()-18,k.getWidth(),18,juce::Justification::centred,1);}
void UCGVoiceWonderEditor::resized(){title.setBounds(30,28,getWidth()-60,45);int w=150;for(int i=0;i<8;i++){int row=i/4,col=i%4;knobs[i].setBounds(55+col*175,115+row*145,w,105);}midi.setBounds(300,385,180,28);}

